const panels=[['p1',1,'display',{heading:'How would you say it?',body:"You're sick and will miss class tomorrow. Think about how you would message a friend, then how you would message your instructor."},0],['p2',2,'multi_select',{heading:'To a friend',quote:"Hey, I'm sick. Can you send me the notes tomorrow?",prompt:'What makes this appropriate for a friend? Select all that apply.',options:['Casual tone','Short message','Assumes familiarity','Gives extensive background'],correct_options:['Casual tone','Short message','Assumes familiarity'],feedback_correct:'Exactly. The message is brief and casual because the writer expects the friend to understand the situation without much explanation.',feedback_hint1:'Almost. Look again at how casual and brief the message is, and what the writer expects the friend to already know.',feedback_hint2:'You are close. Focus on tone, message length, and whether the message assumes shared context.',feedback_partial:'The key features are its casual tone, short length, and the way it assumes the friend already understands the situation.'},1],['p3',3,'multi_select',{heading:'To your instructor',quote:"Prof. Myrick, I am unwell and will not be able to attend tomorrow's class. Could you please let me know if there is anything I should review before our next class?",prompt:'What changed in the message? Select all that apply.',options:['Tone','Wording','Amount of detail','The class itself'],correct_options:['Tone','Wording','Amount of detail'],feedback_correct:'Exactly. The tone, wording, and amount of detail changed. The situation did not.',feedback_hint1:'Almost. Compare the two messages closely: notice how the message sounds, the words it uses, and how much information it provides.',feedback_hint2:'You are close. The class and situation stay the same; focus on the message itself.',feedback_partial:'The message changes its tone, wording, and amount of detail. The underlying situation stays the same.',why_feedback:'Why? Because the audience and the writer’s relationship to that audience are different.'},1],['p4',4,'display',{heading:'What changed?',body:'The situation is the same, but the reader is different. That changes the tone, wording, and amount of detail you use.'},0],['p5',5,'display',{heading:'Key idea',body:'Good writers make choices based on who they are writing to, why they are writing, and the situation.'},0]];for(const[id,order,type,payload,req]of panels)run(`INSERT INTO learning_stack_panels VALUES (?,?,?,?,?,?)`,id,'stack-w1-audience',order,type,JSON.stringify(payload),req);
