const qs=[['q1','single_choice','Which message is more appropriate for an instructor?',{messages:[{label:'A',text:'Send me the assignment details when you get a chance.'},{label:'B',text:'Dear Professor, could you please clarify the requirements for the assignment due Friday?'}]},['A','B'],'B','Yes. Message B better matches the relationship and gives useful context.','Message A communicates the request, but Message B better fits an academic relationship.'],['q2','single_choice','Why is Message B more appropriate?',null,['It is longer.','It uses difficult vocabulary.','Its tone and detail fit the audience and situation.','Academic writing should always be formal.'],'Its tone and detail fit the audience and situation.','Exactly. Effective writing fits the audience, purpose, and situation.','Length and formality alone do not make writing effective. The choices need to fit the audience and situation.']];for(const[qid,type,prompt,stim,opts,expected,fc,fi]of qs){run(`INSERT INTO question_items VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`,qid,'1',type,prompt,stim?JSON.stringify(stim):null,JSON.stringify(opts),expected,fc,fi,'concept-audience','clo1','approved');run(`INSERT INTO quick_check_questions VALUES (?,?,?,?)`,'qc-w1-audience',qid,qid==='q1'?1:2,1);}
const readingText=`University students use technology every day, but frequent technology use does not necessarily mean that students know how to use digital tools effectively for learning. A student may be comfortable using social media, messaging applications, and online entertainment while still struggling to evaluate an online source, organize digital files, protect personal information, or use unfamiliar academic software.\n\nFor this reason, some universities provide digital literacy training for new students. These programs may introduce students to university learning platforms, online research tools, file management, digital communication, cybersecurity, and responsible use of artificial intelligence. Supporters argue that such training can reduce frustration and help students become more independent learners.\n\nHowever, requiring an additional course or training program also creates challenges. Students already have demanding schedules, and universities may assume that every learner needs the same level of digital support. Some students may already possess strong digital skills, while others may need considerably more assistance. A single required course may therefore be too basic for some learners and too fast for others.\n\nA more flexible approach may be useful. Universities could provide a short digital-skills introduction for all students and then offer additional support based on individual needs. Students who demonstrate existing skills could move quickly through basic material, while students who need more support could receive guided practice.\n\nDigital literacy is becoming increasingly important in university education, but institutions should avoid assuming either that all students lack digital skills or that all students already possess them. The most effective approach may be one that identifies what individual learners need and provides appropriate support.`;
content('w1-reading','reading','Should Every University Student Learn Digital Skills?',{title:'Should Every University Student Learn Digital Skills?',estimated_minutes:3,body:readingText,source_label:'Composition 101 · Instructor-approved course reading'},5,'required','learner_marks_complete','act-w1-quickcheck');
